#!/usr/bin/env bash
# Offline Python source compilation smoke-check, not a wheel packaging step.
# Never write generated bytecode into the read-only checkout.
set -euo pipefail
ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd -P)"
export PYTHONPYCACHEPREFIX="${TMPDIR:-/tmp}/system-proxy-ci-pycache"
python3 -m compileall -q "$ROOT/src"
echo "Python source compilation succeeded (bytecode in $PYTHONPYCACHEPREFIX)"
